(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const wx = w1x + Math.sin((x+w1x)*0.01+t*0.15)*8 + Math.cos((y+w1y)*0.012-t*0.1)*6;
  const wy = w1y + Math.cos((y+w1y)*0.01-t*0.18)*8 + Math.sin((x+w1x)*0.011+t*0.12)*6;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.5],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.6],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.4],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.7],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.3],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.55],
    [80+Math.sin(t*0.45+3)*110,40+Math.cos(t*0.65+2)*60,0.11,2.1,0.45],
    [400+Math.cos(t*0.55+1)*70,220+Math.sin(t*0.75+4)*50,0.05,2.8,0.35]
  ];
  let act=0,inh=0,mod=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    act+=Math.sin(d*f-t*sp)*w;
    inh+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    mod+=Math.sin(d*f*1.3-t*sp*0.4+0.8)*w*0.5;
  }
  const wS=src.reduce((s,p)=>s+p[4],0);
  act/=wS;inh/=wS;mod/=wS;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=(Math.sin((sx+sy)*0.12+t*2.5)+Math.sin((sx-sy)*0.1-t*2))*0.2;
  const bg3=Math.sin(sx*0.07+t*0.5)*Math.cos(sy*0.06-t*0.4)*0.3;
  const bg4=Math.sin(sx*0.2+sy*0.15+t*3)*Math.cos(sx*0.15-sy*0.2-t*2.5)*0.15;
  const bg=bg1+bg2+bg3+bg4;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=Math.sin(dist*0.03-ang*5+t*0.8)*Math.cos(dist*0.06+ang*2-t*1.7)*0.3;
  const sp3=Math.sin(dist*0.08-ang*6-t*2.2)*0.15;
  const spiral=sp1+sp2+sp3;
  const r2=Math.tanh((act-inh*0.7+mod*0.3+bg*0.3+spiral)*2.2);
  const fb=Math.sin(r2*3.14)*0.3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+fb)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2=Math.tanh(Math.sin(sx*0.22+t*0.7)*Math.sin(sy*0.18-t*0.5)*2)*0.15;
  const detail=Math.sin(sx*0.4+sy*0.35+t*4)*Math.cos(sx*0.35-sy*0.4-t*3.5)*0.1;
  const blend=reaction*0.55+cell*0.2+cell2*0.1+detail*0.05+spiral*0.1;
  const v=blend*0.5+0.5;
  const pal=[
    [6,12,58],[12,55,95],[18,110,120],[30,165,140],
    [140,190,80],[210,185,60],[220,140,70],[195,90,75],
    [160,55,70],[100,30,65],[50,18,60],[6,12,58]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const r=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.0+(Math.abs(reaction)-0.65)*1.5:1.0;
  const hR=Math.sin(ang*2+t*0.3)*0.08;
  return[
    Math.min(255,((r+hR*40)*lum*edge))|0,
    Math.min(255,((g-hR*10)*lum*edge))|0,
    Math.min(255,((b+hR*30)*lum*edge))|0
  ];
}
